using Godot;
using System;
using System.Linq;
public partial class MigrationScene {
 void CommunityCoopChecks(CoopActor actor){var originalCommunity=game.World.Changes.Community;var originalPieces=game.Building.Pieces.ToList();Vector3 originalPosition=actor.Body.Position;int originalFood=actor.Game.Life.Food;try{
  game.World.Changes.Community=new();Community.Seed(game.World);game.Building.Pieces.Clear();CommunityTestShelter(HostPosition.X+10,HostPosition.Z,1);var bed=game.Building.Pieces.First(p=>p.Def.Function=="bed");actor.Body.Position=new((float)bed.X,(float)bed.Y+.5f,(float)bed.Z+1);var n=Community.Survivors[0];n.State="rescued";n.X=actor.Body.Position.X;n.Y=actor.Body.Position.Y;n.Z=actor.Body.Position.Z;actor.Game.Life.Food=6;int hostFood=game.Life.Food;WithCoopActor(actor,()=>CommunityAction(n.Id+"|recruit"));if(!n.Member||actor.Game.Life.Food!=3||game.Life.Food!=hostFood||Community.Food!=3)throw new Exception("Guest recruitment costs or shared membership failed");WithCoopActor(actor,()=>CommunityAction(n.Id+"|follow"));if(n.Owner!=actor.Identity)throw new Exception("Companion bound to wrong co-op player");WithCoopActor(actor,()=>CommunityAction(n.Id+"|deposit-food"));if(Community.Food!=6||actor.Game.Life.Food!=0||game.Life.Food!=hostFood)throw new Exception("Guest camp deposit changed host inventory");var world=Json.Read<CoopWorld>(Json.Write(WorldSnapshot()));if(!world.Changes.Community.Survivors.Any(s=>s.Member&&s.Owner==actor.Identity))throw new Exception("Community missing from shared world snapshot");var frames=Json.Read<CoopFrame>(Json.Write(FrameFor(actor.Body.Position)));if(!frames.Community.Any(f=>f.Id==n.Id))throw new Exception("NPC missing from guest interest snapshot");GD.Print("PASS / guest recruitment, food conservation, companion ownership and community world/movement replication");
 }finally{game.World.Changes.Community=originalCommunity;game.Building.Pieces.Clear();game.Building.Pieces.AddRange(originalPieces);actor.Body.Position=originalPosition;actor.Game.Life.Food=originalFood;SyncStructures();}}
}
